# ZagBench – BeFannkuch (Python port of BeFannkuch.class.st).
#
# Fannkuch-Redux: count pancake flips across all permutations of 0..n-1.
# Permutations generated by the rotation-based algorithm (Benchmark Game
# reference) so that checksum signs alternate correctly with permutation order.
# Verification values match the Benchmark Game reference for all n.

from benchmark import Benchmark


class BeFannkuch(Benchmark):
    MAIN_ITERATIONS  = 2
    INNER_ITERATIONS = 10

    # Verification table (checksum, max_flips) for n = 1..11, indexed by n-1
    _EXPECTED = [
        [0,      0],   # n=1
        [-1,     1],   # n=2
        [2,      2],   # n=3
        [4,      4],   # n=4
        [11,     7],   # n=5
        [49,     10],  # n=6
        [228,    16],  # n=7
        [1616,   22],  # n=8
        [8629,   30],  # n=9
        [73196,  38],  # n=10
        [556355, 51],  # n=11
    ]

    def inner_benchmark_loop(self, inner_iterations):
        return self._verify(self._solve(inner_iterations), inner_iterations)

    # ------------------------------------------------------------------
    # Rotation-based permutation generator
    # ------------------------------------------------------------------

    def _solve(self, n):
        perm1     = [0] * n                         # [0, 1, ..., n-1]
        count     = [0] * n                         # [1, 2, ..., n]
        perm      = [0] * n                         # working copy for flips
        for i in range(n):
            perm1[i] = i
            count[i] = i + 1
        checksum  = 0
        max_count = 0
        nperm     = 0

        while True:
            # Process current permutation
            if perm1[0] != 0:
                for i in range(n):
                    perm[i] = perm1[i]
                flips = 0
                while perm[0] != 0:
                    k = perm[0]
                    lo, hi = 0, k
                    while lo < hi:
                        perm[lo], perm[hi] = perm[hi], perm[lo]
                        lo += 1
                        hi -= 1
                    flips += 1
                if flips > max_count:
                    max_count = flips
            else:
                flips = 0

            if nperm % 2 == 0:
                checksum += flips
            else:
                checksum -= flips
            nperm += 1

            # Advance to the next permutation via left-rotation
            r = 1
            while True:
                perm0 = perm1[0]
                for i in range(r):
                    perm1[i] = perm1[i + 1]
                perm1[r] = perm0
                count[r] -= 1
                if count[r] > 0:
                    break
                count[r] = r + 1   # reset
                r += 1
                if r >= n:
                    return [checksum, max_count]

    def _verify(self, result, iterations):
        if iterations < 1 or iterations > 11:
            print(f"No verification result for {iterations} found")
            return False
        expected = self._EXPECTED[iterations - 1]
        return result[0] == expected[0] and result[1] == expected[1]
